292		cmd.Dir = ".."
293		var stdout, stderr strings.Builder
294		cmd.Stdout = &stdout
295		cmd.Stderr = &stderr
296		err := cmd.Run()
297		code := 0
298		if err != nil {
299			if exitErr, ok := err.(*exec.ExitError); ok {
300				code = exitErr.ExitCode()
301			} else {
302				t.Fatalf("failed to run command: %v", err)
303			}
304		}
305		return code, stdout.String(), stderr.String()
306	}
