func TestPlan_SpreadByEmptyStringDisablesSpreading(t *testing.T) {
	// Explicit empty string behaves exactly like the field being absent.
	plain := validInput()
	withEmpty := validInput()
	withEmpty.SpreadBy = ""
	p1, err := MakeReleasePlan(plain)
	if err != nil {
		t.Fatal(err)
